{"code": "const [r1, r2] = await Promise.all([
  tools.grep({pattern:"S1824|S1840|YonedaComparison|bicategorical Yoneda", path:"dag"}),
  tools.grep({pattern:"S1824|S1840|YonedaComparison|bicategorical Yoneda", path:"coord"})
]);
console.log("--- dag ---");
console.log(r1.matches.slice(0,20).map(m=>`${m.path}:${m.lineNumber}: ${m.line.trim()}`).join("\n") || "(none)");
console.log("--- coord ---");
console.log(r2.matches.slice(0,20).map(m=>`${m.path}:${m.lineNumber}: ${m.line.trim()}`).join("\n") || "(none)");
", "description": "Search DAG/coord for package"}

